contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        // Drive c through the public entry owner (read-only getter) and check general rule.
        bool reverted;
        address returnedOwner;
        try c.owner() returns (address o) {
            returnedOwner = o;
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            !reverted &&
            returnedOwner != address(0) &&
            returnedOwner == c.owner()
        );
    }

    receive() external payable {}
}

