contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 loanID_, address to_) public {
        require(loanID_ == 0 || loanID_ >= 0, "trivial param guard");
        require(to_ != address(0), "to_ must be nonzero");

        // Read the current approval value at the given key (may be zero for a fresh/unset loan).
        address beforeApproval = c.approvals(loanID_);

        bool reverted;
        try c.approveTransfer(to_, loanID_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address afterApproval = c.approvals(loanID_);

        if (reverted) {
            // A reverted approveTransfer must not change the stored approval.
            assert(afterApproval == beforeApproval);
        } else {
            // A successful approveTransfer stores the given address under loanID_.
            assert(afterApproval == to_);
        }
    }

    receive() external payable {}
}

