contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 amount_,
        uint256 interest_,
        uint256 loanToCollateral_,
        uint256 duration_
    ) public {
        require(loanToCollateral_ > 0);

        uint256 beforeLen = 0;
        while (true) {
            (bool ok, ) = address(c).staticcall(abi.encodeWithSignature("requests(uint256)", beforeLen));
            if (!ok) break;
            beforeLen++;
        }

        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        (uint256 rAmount, uint256 rInterest, uint256 rLoanToCollateral, uint256 rDuration, bool rActive) = c.requests(reqID);

        bool appended;
        (bool ok2, ) = address(c).staticcall(abi.encodeWithSignature("requests(uint256)", beforeLen));
        appended = ok2;

        assert(
            reqID == beforeLen &&
            appended &&
            rAmount == amount_ &&
            rInterest == interest_ &&
            rLoanToCollateral == loanToCollateral_ &&
            rDuration == duration_ &&
            rActive
        );
    }
}

