contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint256 amount_,
        uint256 interest_,
        uint256 loanToCollateral_,
        uint256 duration_,
        uint256 repaid_,
        bool repayDirect_
    ) public {
        require(loanToCollateral_ > 0, "loanToCollateral must be positive");

        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        uint256 loanID = c.clearRequest(reqID, repayDirect_, false);

        C.Loan memory beforeLoan = c.getLoan(loanID);
        bool beforeDefaulted = c.isDefaulted(loanID);

        bool reverted;
        try c.repayLoan(loanID, repaid_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        C.Loan memory afterLoan = c.getLoan(loanID);

        if (beforeDefaulted) {
            assert(reverted && afterLoan.amount == beforeLoan.amount);
        } else {
            uint256 cap = beforeLoan.amount;
            uint256 effective = repaid_ > cap ? cap : repaid_;
            assert(!reverted && afterLoan.amount == beforeLoan.amount - effective);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint256 amount_,
        uint256 interest_,
        uint256 loanToCollateral_,
        uint256 duration_,
        uint256 repaid_,
        bool repayDirect_
    ) public {
        require(loanToCollateral_ > 0, "loanToCollateral must be positive");
        require(amount_ > 0, "amount must be positive");

        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        uint256 loanID = c.clearRequest(reqID, repayDirect_, false);

        C.Loan memory beforeLoan = c.getLoan(loanID);
        bool beforeDefaulted = c.isDefaulted(loanID);

        bool reverted;
        try c.repayLoan(loanID, repaid_) { reverted = false; } catch { reverted = true; }

        C.Loan memory afterLoan = c.getLoan(loanID);

        uint256 cap = beforeLoan.amount;
        uint256 effective = repaid_ > cap ? cap : repaid_;
        bool unchanged = afterLoan.amount == beforeLoan.amount;
        bool reduced = afterLoan.amount == beforeLoan.amount - effective;

        assert(beforeDefaulted ? (reverted && unchanged) : (!reverted && reduced));
    }

    receive() external payable {}
}

