    }

    function run(uint256 reqID_, uint256 loanID_) public payable {
        require(true);

        // Create a loan: the test contract becomes the lender via clearRequest.
        c.requestLoan(1000, 0, 1, 1 days);
        uint256 loanID = c.clearRequest(reqID_, true, false);

        // The caller (this test contract) is the lender of loanID.
        bool reverted;
        try c.approveTransfer(address(0xdead), loanID) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Rule: approveTransfer on an existing loan must NOT revert when the caller is the lender.
        assert(!reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 reqID_, uint256 loanID_, address to_, uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public {
        require(loanToCollateral_ != 0, "loanToCollateral must be nonzero");
        require(duration_ > 0, "duration must be positive");
        c.requestLoan(amount_, interest_, loanToCollateral_, duration_);
        c.clearRequest(reqID_, false, false);

        bool loanExists = loanID_ < c.loansLength();
        require(loanExists, "loan must exist for this test");

        c.approveTransfer(to_, loanID_);
        address beforeLender = c.getLoan(loanID_).lender;

        bool reverted;
        if (to_ == address(this)) {
            try c.transferOwnership(loanID_) { reverted = false; } catch { reverted = true; }
        } else {
            try c.transferOwnership(loanID_) { reverted = false; } catch { reverted = true; }
        }

        address afterLender = c.getLoan(loanID_).lender;

        if (msg.sender == c.approvals(loanID_)) {
            assert(!reverted && afterLender == msg.sender && c.approvals(loanID_) == address(0));
        } else {
            assert(reverted && afterLender == beforeLender && c.approvals(loanID_) == to_);
        }
    }

    receive() external payable {}
}

